import{_ as n,a0 as p,w as r,s as d,ao as l,I as a,a1 as t,A as o,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211001 How to Install Google Chrome on Debian and Kali Linux","title":"如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器","tag":"202110","desc":""},"relativePath":"202110/20211001 How to Install Google Chrome on Debian and Kali Linux.md","filePath":"[post].md"}'),m={name:"202110/20211001 How to Install Google Chrome on Debian and Kali Linux.md"};function h(u,e,b,g,C,f){const s=p("Link");return r(),d("div",null,[e[29]||(e[29]=l('<h1 id="如何在-debian-和-kali-linux-上安装-chrome-浏览器" tabindex="-1">如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器 <a class="header-anchor" href="#如何在-debian-和-kali-linux-上安装-chrome-浏览器" aria-label="Permalink to “如何在 Debian 和 Kali Linux 上安装 Chrome 浏览器”">​</a></h1><blockquote><p>Debian 和基于 Debian 的 Kali Linux 将 Firefox 作为默认的网页浏览器。但这并不意味着你不能在其中安装其他网页浏览器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/18/175716cfvxnvf05b5je1ax.jpg" alt=""></p><p>Chrome 浏览器非常流行，你可能已经在其他系统上使用它了。如果你想在 Debian 上安装 Chrome，你肯定可以这样做。</p><p>你在 Debian 的软件库中找不到 Chrome，因为它不是开源软件，但你可以从 Chrome 网站下载并安装它。</p><p>在本教程中，我将向你展示在 Debian 上安装 Chrome 的两种方法：</p><ul><li>GUI 方法</li><li>命令行方法</li></ul><p>让我们先从 GUI 方法开始。</p><blockquote><p>注意：我在这里的例子中使用的是 Debian，但由于 Kali Linux 是基于 Debian 的，所以同样的方法也适用于 Kali Linux。</p></blockquote><h3 id="方法-1-在-debian-上以图形方式安装-chrome-浏览器" tabindex="-1">方法 1: 在 Debian 上以图形方式安装 Chrome 浏览器 <a class="header-anchor" href="#方法-1-在-debian-上以图形方式安装-chrome-浏览器" aria-label="Permalink to “方法 1: 在 Debian 上以图形方式安装 Chrome 浏览器”">​</a></h3><p>这是一个不费吹灰之力的方法。你去 Chrome 网站，下载 deb 文件，然后双击它来安装它。我将详细地展示这些步骤，这样你就能很容易地掌握了。</p><p>前往 Chrome 的网站。</p>',12)),a("p",null,[t(s,{href:"https://www.google.com/chrome/"},{default:o(()=>[...e[0]||(e[0]=[i("Get Google Chrome",-1)])]),_:1})]),e[30]||(e[30]=l('<p>你会看到下载 Chrome 的选项。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/download-chrome-on-debian.webp?resize=800%2C344&amp;ssl=1" alt="Click on the Download Chrome button"></p><p>当你点击下载按钮时，它会给你两个下载安装文件的选项。选择写着 Debian/Ubuntu 的那个。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/downloading-google-chrome.webp?resize=800%2C512&amp;ssl=1" alt="Download the Chrome installer file for Debian"></p><p><strong>请注意，Chrome 浏览器不适用于 32 位系统。</strong></p><p>接下来，你应该选择将文件保存到电脑中，而不是在软件中心打开进行安装。这样一来，下载的文件将被保存在下载文件夹中，而不是临时目录中。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/save-downloaded-chrome-installer-file-debian.webp?resize=800%2C430&amp;ssl=1" alt="Save the downloaded DEB file for Google Chrome"></p><p>进入下载文件夹，右击下载的 DEB 文件，选择用 “Software Install” 打开它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/open-deb-file-with-software-install.webp?resize=800%2C419&amp;ssl=1" alt="Right click on the downloaded DEB file and open with Software Install"></p><p>它将打开软件中心，你应该看到现在安装 Chrome 浏览器的选项。点击安装按钮。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/installing-chrome-debian.webp?resize=800%2C408&amp;ssl=1" alt="Click on the install button"></p><p>你会被要求输入账户的密码。这是你用来登录系统的同一密码。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/enter-account-password-while-installing-deb-file.webp?resize=800%2C420&amp;ssl=1" alt="Enter your account’s password"></p><p>在不到一分钟的时间里，Chrome 就会安装完毕。你现在应该看到一个删除选项，这表明软件已经安装完毕。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/09/chrome-installed-debian.webp?resize=800%2C384&amp;ssl=1" alt="Chrome is now installed"></p><p>当 Chrome 在 Debian 上安装完毕，在系统菜单中搜索它并启动它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/start-chrome-debian.webp?resize=800%2C276&amp;ssl=1" alt="Start Google Chrome"></p><p>它将要求成为你的默认浏览器，并将崩溃报告发送给谷歌。你可以取消勾选这两个选项。然后你就可以看到谷歌浏览器的窗口。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/09/Chrom-in-Debian.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>如果你登录了你的谷歌账户，你应该可以在这里同步你的密码、书签和其他浏览数据。好好体验吧！</p><p>还有一点，安装完 Chrome 后，你可以从系统中删除下载的 DEB 文件。不再需要它了，甚至在卸载 Chrome 时也不需要。</p><h3 id="方法-2-在-debian-上从终端安装-chrome" tabindex="-1">方法 2：在 Debian 上从终端安装 Chrome <a class="header-anchor" href="#方法-2-在-debian-上从终端安装-chrome" aria-label="Permalink to “方法 2：在 Debian 上从终端安装 Chrome”">​</a></h3><p>你刚才看到的内容可以在终端中轻松实现。</p>',23)),a("p",null,[e[2]||(e[2]=i("首先，确保你的软件包缓存已经刷新，并且你已经安装了 ",-1)),e[3]||(e[3]=a("code",null,"wget",-1)),e[4]||(e[4]=i("，用于 ",-1)),t(s,{href:"https://itsfoss.com/download-files-from-linux-terminal/"},{default:o(()=>[...e[1]||(e[1]=[i("在终端中从网上下载文件",-1)])]),_:1}),e[5]||(e[5]=i("。",-1))]),e[31]||(e[31]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install wget</span></span></code></pre></div><p>接下来是下载 Chrome 的 .deb 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb</span></span></code></pre></div>',3)),a("p",null,[e[7]||(e[7]=i("下载后，你可以用 ",-1)),e[8]||(e[8]=a("code",null,"apt",-1)),e[9]||(e[9]=i(" 命令 ",-1)),t(s,{href:"https://itsfoss.com/install-deb-files-ubuntu/"},{default:o(()=>[...e[6]||(e[6]=[i("在终端安装 deb 文件",-1)])]),_:1}),e[10]||(e[10]=i("，像这样：",-1))]),e[32]||(e[32]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ./google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p>安装完成后，你就可以开始使用 Chrome 了。</p><h3 id="额外提示-更新-chrome" tabindex="-1">额外提示：更新 Chrome <a class="header-anchor" href="#额外提示-更新-chrome" aria-label="Permalink to “额外提示：更新 Chrome”">​</a></h3><p>这两种方法都会将谷歌的软件库添加到你的系统中。你可以在你的 <code>sources.list.d</code> 目录中看到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/apt/sources.list.d/google-chrome.list</span></span></code></pre></div>',5)),a("p",null,[e[12]||(e[12]=i("这意味着 Chrome 将与 Debian 和 Kali Linux 中的其他系统更新一起被更新。你知道 ",-1)),t(s,{href:"https://linuxhandbook.com/update-kali-linux/"},{default:o(()=>[...e[11]||(e[11]=[i("如何在命令行中更新你的 Kali Linux",-1)])]),_:1}),e[13]||(e[13]=i(" 或 Debian 系统么？只要使用这个命令：",-1))]),e[33]||(e[33]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><h3 id="从你的系统中卸载-chrome" tabindex="-1">从你的系统中卸载 Chrome <a class="header-anchor" href="#从你的系统中卸载-chrome" aria-label="Permalink to “从你的系统中卸载 Chrome”">​</a></h3><p>即使你选择用 GUI 方法在 Debian 上安装 Chrome，你也必须使用终端来删除它。</p><p>不要担心。这其实只是一个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge google-chrome-stable</span></span></code></pre></div><p>根据要求输入你的账户密码。当你输入密码时，屏幕上没有任何显示。这没关系。输入它并按回车键，确认删除。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/remove-google-chrome-ubuntu.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>好了，就这些了。我希望你觉得这个教程有帮助。</p><hr>',9)),a("p",null,[e[15]||(e[15]=i("via: ",-1)),t(s,{href:"https://itsfoss.com/install-chrome-debian-kali-linux/"},{default:o(()=>[...e[14]||(e[14]=[i("https://itsfoss.com/install-chrome-debian-kali-linux/",-1)])]),_:1})]),a("p",null,[e[20]||(e[20]=i("作者：",-1)),t(s,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...e[16]||(e[16]=[i("Abhishek Prakash",-1)])]),_:1}),e[21]||(e[21]=i(" 选题：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[17]||(e[17]=[i("lujun9972",-1)])]),_:1}),e[22]||(e[22]=i(" 译者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:o(()=>[...e[18]||(e[18]=[i("geekpi",-1)])]),_:1}),e[23]||(e[23]=i(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:o(()=>[...e[19]||(e[19]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[26]||(e[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[24]||(e[24]=[i("LCTT",-1)])]),_:1}),e[27]||(e[27]=i(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:o(()=>[...e[25]||(e[25]=[i("Linux中国",-1)])]),_:1}),e[28]||(e[28]=i(" 荣誉推出",-1))])])}const x=n(m,[["render",h]]);export{c as __pageData,x as default};
